/// The blast resistance of a block name (binary search over the
/// sorted index, the data through the registration order); the
/// 0.0 default the registry-foreign name rides (the palette's
/// own synthetic rows — the wheat ladder's stage words the
/// registry never spoke).
pub fn resistance(name: &str) -> f32 {
    match RESISTANCE_SORTED
        .binary_search_by(|probe| RESISTANCE_NAMES[*probe as usize].cmp(name))
    {
        Ok(pos) => RESISTANCE_VALUES[RESISTANCE_SORTED[pos] as usize],
        Err(_) => 0.0,
    }
}
